let effectIndex: ReadonlyMap<string, CatalogEffect> | null = null;

/** The catalog entry of a built-in effect type; undefined for an unknown (or plugin) type. */
export function catalogEffect(type: string): CatalogEffect | undefined {
  effectIndex ??= new Map(EFFECT_CATALOG.map((e) => [e.type, e]));
  return effectIndex.get(type);
}
